import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { caretDown, caretLeft, caretRight, caretUp } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { PanelResizeController } from "./resizer";

/**
 * @since 0.0.11
 * @status beta
 *
 * A generic resizable and collapsible side panel container.
 *
 * @slot - Default slot for the panel content.
 *
 * @part base - The component's base wrapper.
 * @part container - The resizable container that wraps the slotted content.
 * @part content - The inner content wrapper.
 * @part resizer - The drag handle used to resize the panel.
 * @part collapse-button - The button used to collapse/expand the panel.
 */
@Component({
	tag: "hbr-panel",
	styleUrl: "panel.scss",
	shadow: true,
})
export class Panel {
	static panelId = 0;
	private panelId = `hbr-panel__${++Panel.panelId}`;
	private resizeController = new PanelResizeController({
		getSize: () => this.size,
		setSize: (size) => {
			this.size = size;
		},
		getMinSize: () => this.minSize,
		getMaxSize: () => this.maxSize,
		isResizable: () => this.resizable,
		isCollapsed: () => this.collapsed,
		getAxis: () => (this.isVertical() ? "y" : "x"),
		getDirection: () =>
			this.placement === "right" || this.placement === "bottom" ? -1 : 1,
		onResizeStart: () => {
			this.isResizing = true;
		},
		onResize: (size) => {
			this.hbrPanelResizing.emit({ size });
		},
		onResizeEnd: () => {
			this.isResizing = false;
		},
	});

	@Element() host: HTMLHbrPanelElement;

	/** Enables and shows the collapse button */
	@Prop({ reflect: true }) collapsable = false;

	/** Enables drag resizing */
	@Prop({ reflect: true }) resizable = true;

	/** Controls collapsed state */
	@Prop({ mutable: true, reflect: true }) collapsed = false;

	/** Current size of the panel along its resize axis (width for left/right, height for top/bottom) */
	@Prop({ mutable: true, reflect: true }) size = 250;

	/** Minimum allowed size when resizing */
	@Prop({ reflect: true }) minSize = 24;

	/** Maximum allowed size when resizing */
	@Prop({ reflect: true }) maxSize = 800;

	/** Side the panel is anchored to. The collapse button and resizer appear on the opposite edge. */
	@Prop({ reflect: true }) placement: "top" | "right" | "bottom" | "left" =
		"left";

	@State() isResizing = false;

	/** Emits the collapsed state whenever the toggle button is used */
	@Event({ eventName: "hbr-panel-collapsed", bubbles: false })
	hbrPanelCollapsed!: EventEmitter<{ collapsed: boolean }>;

	/** Emits the current size while the user is resizing */
	@Event({ eventName: "hbr-panel-resizing", bubbles: false })
	hbrPanelResizing!: EventEmitter<{ size: number }>;

	componentWillLoad() {
		this.size = this.clampSize(this.size);
		this.host.style.setProperty("--size", `${this.size}px`);
	}

	disconnectedCallback() {
		this.resizeController?.destroy();
	}

	@Watch("size")
	protected onSizeChange(newValue: number) {
		this.size = this.clampSize(newValue);
		this.host.style.setProperty("--size", `${this.size}px`);
	}

	@Watch("minSize")
	@Watch("maxSize")
	protected onLimitsChange() {
		this.size = this.clampSize(this.size);
	}

	private clampSize(size: number): number {
		return this.resizeController.clampSize(size);
	}

	private onResizeStart = (event: MouseEvent) => {
		this.resizeController.start(event);
	};

	private isVertical(): boolean {
		return this.placement === "top" || this.placement === "bottom";
	}

	private onToggleCollapse = () => {
		this.collapsed = !this.collapsed;
		this.hbrPanelCollapsed.emit({ collapsed: this.collapsed });
	};

	render() {
		const vertical = this.isVertical();
		let containerProp: { inert?: boolean; style?: { [k: string]: string } } =
			{};
		if (this.collapsed) {
			containerProp = { inert: true };
		}
		if (this.resizable && !this.collapsed) {
			const sizeStyle: { [k: string]: string } = vertical
				? { minHeight: `${this.size}px`, height: `${this.size}px` }
				: { minWidth: `${this.size}px`, width: `${this.size}px` };
			containerProp = {
				...containerProp,
				style: sizeStyle,
			};
		}

		const collapseIconName = this.collapsed
			? this.placement === "right"
				? "caret-left"
				: this.placement === "left"
				  ? "caret-right"
				  : this.placement === "bottom"
					  ? "caret-up"
					  : "caret-down"
			: this.placement === "right"
			  ? "caret-right"
			  : this.placement === "left"
				  ? "caret-left"
				  : this.placement === "bottom"
					  ? "caret-down"
					  : "caret-up";

		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const fallbackByName: Record<string, () => string> = {
			"caret-left": caretLeft,
			"caret-right": caretRight,
			"caret-up": caretUp,
			"caret-down": caretDown,
		};
		const collapseIconAsset =
			customSystemIcons?.[collapseIconName] || fallbackByName[collapseIconName];

		return (
			<Host>
				<div
					part="base"
					class={{
						panel: true,
						"panel--resizable": this.resizable,
						"panel--resizing": this.isResizing,
						"panel--collapsed": this.collapsed,
						[`panel--placement-${this.placement}`]: true,
					}}
				>
					<div
						part="container"
						class={{
							panel__container: true,
							"panel__container-collapsed": this.collapsed,
						}}
						id={this.panelId}
						{...containerProp}
					>
						<div part="content" class="panel__content">
							<slot />
						</div>
						<span
							part="resizer"
							class={{
								panel__resizer: true,
								"panel__resizer-border": this.resizable,
							}}
							onMouseDown={this.onResizeStart}
							role="separator"
							aria-orientation={vertical ? "horizontal" : "vertical"}
							aria-label="Resize panel"
							aria-valuemin={this.minSize}
							aria-valuemax={this.maxSize}
							aria-valuenow={this.size}
						/>
					</div>
					{this.collapsable && (
						<button
							part="collapse-button"
							class="collapse-button"
							type="button"
							onClick={this.onToggleCollapse}
							aria-expanded={`${!this.collapsed}`}
							aria-controls={this.panelId}
							aria-label={this.collapsed ? "Expand panel" : "Collapse panel"}
						>
							<slot name="collapse-icon">
								<hbr-icon asset={collapseIconAsset} />
							</slot>
						</button>
					)}
				</div>
			</Host>
		);
	}
}
