export type PanelAxis = "x" | "y";

export interface PanelResizeControllerOptions {
	getSize: () => number;
	setSize: (size: number) => void;
	getMinSize: () => number;
	getMaxSize: () => number;
	isResizable: () => boolean;
	isCollapsed: () => boolean;
	/** Axis the panel resizes along: "x" for horizontal panels, "y" for vertical. */
	getAxis?: () => PanelAxis;
	/** Direction multiplier: 1 when dragging in the positive axis direction grows the panel, -1 otherwise. */
	getDirection?: () => 1 | -1;
	onResizeStart?: () => void;
	onResize?: (size: number) => void;
	onResizeEnd?: () => void;
}

export class PanelResizeController {
	private resizing = false;
	startCoord = 0;
	startSize = 0;

	constructor(private options: PanelResizeControllerOptions) {}

	public get isResizing(): boolean {
		return this.resizing;
	}

	public destroy() {
		this.stop();
	}

	public clampSize(size: number): number {
		const safeMin = Number.isFinite(this.options.getMinSize())
			? this.options.getMinSize()
			: 120;
		const safeMax = Number.isFinite(this.options.getMaxSize())
			? this.options.getMaxSize()
			: 700;
		const min = Math.min(safeMin, safeMax);
		const max = Math.max(safeMin, safeMax);
		const value = Number.isFinite(size) ? size : 320;

		return Math.min(Math.max(value, min), max);
	}

	private getAxis(): PanelAxis {
		return this.options.getAxis?.() ?? "x";
	}

	private getDirection(): 1 | -1 {
		return this.options.getDirection?.() ?? 1;
	}

	public start = (event: MouseEvent) => {
		if (!this.options.isResizable() || this.options.isCollapsed()) {
			return;
		}

		event.preventDefault();
		this.resizing = true;
		this.startCoord = this.getAxis() === "y" ? event.clientY : event.clientX;
		this.startSize = this.options.getSize();

		this.options.onResizeStart?.();

		window.addEventListener("mousemove", this.handleMove);
		window.addEventListener("mouseup", this.handleEnd);
	};

	private handleMove = (event: MouseEvent) => {
		if (!this.resizing) {
			return;
		}

		const current = this.getAxis() === "y" ? event.clientY : event.clientX;
		const delta = (current - this.startCoord) * this.getDirection();
		const nextSize = this.clampSize(this.startSize + delta);

		this.options.setSize(nextSize);
		this.options.onResize?.(nextSize);
	};

	private handleEnd = () => {
		this.stop();
	};

	private stop() {
		if (!this.resizing) {
			return;
		}

		this.resizing = false;
		window.removeEventListener("mousemove", this.handleMove);
		window.removeEventListener("mouseup", this.handleEnd);
		this.options.onResizeEnd?.();
	}
}
